<?php $__env->startSection('actions'); ?><button class="btn btn-outline-secondary" onclick="window.print()">Print</button> <?php if($sale->status==='draft'): ?><?php if (app(\Illuminate\Contracts\Auth\Access\Gate::class)->check('sales.edit')): ?><a class="btn btn-outline-primary" href="<?php echo e(route('sales.edit',$sale)); ?>">Edit</a><?php endif; ?> <?php if (app(\Illuminate\Contracts\Auth\Access\Gate::class)->check('sales.post')): ?><form class="d-inline" method="POST" action="<?php echo e(route('sales.post',$sale)); ?>"><?php echo csrf_field(); ?><button class="btn btn-success" onclick="return confirm('Post this sale?')">Post Sale</button></form><?php endif; ?>@endif@endsection
<?php $__env->startSection('content'); ?><div class="card card-body mb-3"><div class="row"><div class="col"><b>Customer</b><br><?php echo e($sale->customer?->name ?? 'Walk-in'); ?></div><div class="col"><b>Warehouse</b><br><?php echo e($sale->warehouse->name); ?></div><div class="col"><b>Date</b><br><?php echo e($sale->sale_date->format('Y-m-d')); ?></div><div class="col"><b>Status</b><br><?php echo e(strtoupper($sale->status)); ?></div></div></div><div class="card"><table class="table mb-0"><thead><tr><th>Product</th><th class="money">Qty</th><th class="money">Price</th><th class="money">Discount</th><th class="money">Tax</th><th class="money">Total</th></tr></thead><tbody><?php $__currentLoopData = $sale->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><?php echo e($i->product->name); ?></td><td class="money"><?php echo e($i->quantity); ?></td><td class="money"><?php echo e(number_format($i->unit_price,4)); ?></td><td class="money"><?php echo e(number_format($i->discount,2)); ?></td><td class="money"><?php echo e(number_format($i->tax,2)); ?></td><td class="money"><?php echo e(number_format($i->line_total,2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody><tfoot><tr><th colspan="5" class="text-end">Grand Total</th><th class="money"><?php echo e(number_format($sale->grand_total,2)); ?></th></tr><tr><th colspan="5" class="text-end">Paid / Due</th><th class="money"><?php echo e(number_format($sale->paid_amount,2)); ?> / <?php echo e(number_format($sale->due_amount,2)); ?></th></tr></tfoot></table></div><?php $__env->stopSection(); ?>

